{slug:"molarity-calculator",category:"science",shortDescription:"Calculate molar concentration from moles of solute and solution volume.",intro:"Calculate molarity from the amount of solute in moles and the total solution volume in liters. This certified deterministic calculator evaluates the standard concentration relationship from validated numeric inputs.",formulaExplanation:"Molarity is M = n/V, where n is moles of solute and V is total solution volume in liters.",assumptions:["Solution volume must be greater than zero.","The volume input is the total solution volume, not solvent volume.","Use moles and liters for a result in mol/L."],faq:[{question:"What volume should I enter?",answer:"Enter the final total solution volume in liters."},{question:"Can the solution volume be zero?",answer:"No. Molarity divides by solution volume, so it must be positive."}],relatedSlugs:["molality-calculator"],keywords:["molarity calculator","moles per liter","molar concentration"]},
{slug:"molality-calculator",category:"science",shortDescription:"Calculate molal concentration from moles of solute and solvent mass.",intro:"Calculate molality from the amount of solute in moles and the mass of solvent in kilograms. This certified deterministic calculator keeps solvent mass distinct from total solution mass.",formulaExplanation:"Molality is m = n/mass of solvent (kg).",assumptions:["Solvent mass must be greater than zero.","Use solvent mass rather than total solution mass.","Use moles and kilograms for a result in mol/kg."],faq:[{question:"Does molality use solution volume?",answer:"No. Molality uses the mass of the solvent in kilograms."},{question:"Can solvent mass be zero?",answer:"No. The formula divides by solvent mass, so it must be positive."}],relatedSlugs:["molarity-calculator"],keywords:["molality calculator","moles per kilogram","molal concentration"]},
{slug:"molecular-weight-calculator",category:"science",shortDescription:"Calculate formula mass from a chemical formula.",intro:"Parse a chemical formula deterministically and sum standard atomic weights across elements, subscripts and supported nested groups.",formulaExplanation:"Formula mass is M = Σ(nᵢAᵢ), the sum of each element count multiplied by its atomic weight.",assumptions:["Element symbols are case-sensitive.","Parentheses and square-bracket groups are supported.","Hydrates, charges and dot notation are not currently supported."],faq:[{question:"Can it parse grouped formulas?",answer:"Yes. Parentheses and square brackets can be nested."},{question:"Does it recognize every named element?",answer:"The parser includes symbols for all 118 currently named elements."}],relatedSlugs:["moles-calculator"],keywords:["molecular weight calculator","molar mass","chemical formula mass"]},
{slug:"moles-calculator",category:"science",shortDescription:"Calculate moles from mass and molar mass.",intro:"Calculate amount of substance from sample mass and positive molar mass using the certified deterministic chemistry engine.",formulaExplanation:"Moles are n = m/M.",assumptions:["Mass is non-negative.","Molar mass must be positive.","Use compatible mass units."],faq:[{question:"What is molar mass?",answer:"It is mass per mole of the substance."},{question:"Can molar mass be zero?",answer:"No, because the formula divides by molar mass."}],relatedSlugs:["molecular-weight-calculator","molarity-calculator"],keywords:["moles calculator","mass to moles","molar mass"]},
{slug:"dilution-calculator",category:"science",shortDescription:"Calculate final concentration after dilution.",intro:"Calculate final concentration from initial concentration and volumes while conserving the amount of solute.",formulaExplanation:"C₂ = C₁V₁/V₂.",assumptions:["Final volume must be positive.","Concentration and initial volume are non-negative.","Use compatible volume units."],faq:[{question:"What stays constant during dilution?",answer:"This model assumes the amount of solute is conserved."},{question:"Must the volumes use the same units?",answer:"Yes, use compatible volume units."}],relatedSlugs:["molarity-calculator","solution-concentration-calculator"],keywords:["dilution calculator","C1V1 C2V2","solution dilution"]},
{slug:"ph-calculator",category:"science",shortDescription:"Calculate pH from hydrogen-ion concentration.",intro:"Calculate pH deterministically from a positive hydrogen-ion concentration.",formulaExplanation:"pH = -log₁₀[H⁺].",assumptions:["Hydrogen-ion concentration must be positive.","Concentration is interpreted in mol/L.","This is the direct concentration definition, not an activity correction model."],faq:[{question:"Why must concentration be positive?",answer:"The logarithm is undefined for zero or negative concentration."},{question:"Does this model activity coefficients?",answer:"No. It uses the supplied hydrogen-ion concentration directly."}],relatedSlugs:["molarity-calculator"],keywords:["pH calculator","hydrogen ion concentration","negative log H"]},
{slug:"ideal-gas-law-calculator",category:"science",shortDescription:"Calculate ideal-gas pressure from moles, temperature and volume.",intro:"Calculate pressure using the ideal gas law with an explicit gas constant for liters, atmospheres, moles and kelvin.",formulaExplanation:"P = nRT/V.",assumptions:["Volume must be positive.","Temperature is absolute temperature in kelvin.","The gas is modeled as ideal."],faq:[{question:"What units does this version use?",answer:"Liters, atmospheres, moles and kelvin."},{question:"Does it model non-ideal gases?",answer:"No. It applies the ideal gas law."}],relatedSlugs:["gas-density-calculator"],keywords:["ideal gas law calculator","PV nRT","gas pressure"]},
{slug:"gas-density-calculator",category:"science",shortDescription:"Calculate ideal-gas density.",intro:"Calculate ideal-gas density from pressure, molar mass and absolute temperature using deterministic SI-compatible constants.",formulaExplanation:"ρ = PM/(RT).",assumptions:["Temperature must be positive kelvin.","Pressure and molar mass are non-negative.","The gas is modeled as ideal."],faq:[{question:"What is the result unit?",answer:"With the displayed inputs and gas constant, density is in g/L."},{question:"Is this for real gases?",answer:"It is an ideal-gas approximation."}],relatedSlugs:["ideal-gas-law-calculator"],keywords:["gas density calculator","ideal gas density","PM RT"]},
{slug:"percent-composition-calculator",category:"science",shortDescription:"Calculate mass percent of a component.",intro:"Calculate the percentage of total sample mass contributed by a selected component.",formulaExplanation:"Percent composition = component mass / total mass × 100.",assumptions:["Total mass must be positive.","Component mass is non-negative.","Inputs use compatible mass units."],faq:[{question:"Can the result exceed 100%?",answer:"The mathematical engine reports the supplied ratio; ensure component mass is physically consistent with total mass."},{question:"Do units cancel?",answer:"Yes, when both masses use the same unit."}],relatedSlugs:["solution-concentration-calculator"],keywords:["percent composition calculator","mass percent","composition by mass"]},
{slug:"solution-concentration-calculator",category:"science",shortDescription:"Calculate mass concentration of a solution.",intro:"Calculate solute mass per total solution volume as a deterministic mass concentration.",formulaExplanation:"c = m/V.",assumptions:["Solution volume must be positive.","Solute mass is non-negative.","The default interpretation is grams per liter."],faq:[{question:"Is this molarity?",answer:"No. This calculator uses solute mass rather than moles."},{question:"What volume is used?",answer:"Use the final total solution volume."}],relatedSlugs:["molarity-calculator","dilution-calculator"],keywords:["solution concentration calculator","grams per liter","mass concentration"]},
{slug:"stoichiometry-calculator",category:"science",shortDescription:"Calculate target moles from a stoichiometric ratio.",intro:"Convert known moles to target moles using coefficients from a balanced chemical equation.",formulaExplanation:"n₂ = n₁(ν₂/ν₁).",assumptions:["The chemical equation is already balanced.","Known coefficient must be positive.","Coefficients and moles are supplied explicitly."],faq:[{question:"Does this balance equations?",answer:"No. Enter coefficients from an already balanced equation."},{question:"What does the ratio represent?",answer:"It is the mole ratio between target and known species."}],relatedSlugs:["moles-calculator"],keywords:["stoichiometry calculator","mole ratio","chemical coefficients"]},
{slug:"half-life-calculator",category:"science",shortDescription:"Calculate remaining amount after half-life decay.",intro:"Calculate the remaining amount after elapsed time under a constant first-order half-life model.",formulaExplanation:"N = N₀(1/2)^(t/t½).",assumptions:["Half-life must be positive.","Initial amount and elapsed time are non-negative.","Half-life remains constant."],faq:[{question:"What happens after two half-lives?",answer:"One quarter of the initial amount remains."},{question:"Can elapsed time be zero?",answer:"Yes. The remaining amount then equals the initial amount."}],relatedSlugs:[],keywords:["half life calculator","radioactive decay","exponential decay"]},
{slug:"nernst-equation-calculator",category:"science",shortDescription:"Calculate electrochemical cell potential with the Nernst equation.",intro:"Calculate cell potential from standard potential, absolute temperature, electron count and positive reaction quotient.",formulaExplanation:"E = E° - (RT/nF) ln Q.",assumptions:["Temperature, electron count and reaction quotient must be positive.","R and F use SI constants.","Inputs describe the chosen reaction convention."],faq:[{question:"Why must Q be positive?",answer:"The natural logarithm requires a positive reaction quotient."},{question:"What happens when Q equals 1?",answer:"ln(1)=0, so E equals the standard potential."}],relatedSlugs:["voltage-calculator"],keywords:["Nernst equation calculator","cell potential","electrochemistry"]},
{slug:"beer-lambert-law-calculator",category:"science",shortDescription:"Calculate absorbance with the Beer-Lambert law.",intro:"Calculate absorbance from molar absorptivity, optical path length and concentration.",formulaExplanation:"A = εbc.",assumptions:["Inputs are non-negative.","Units for ε, path length and concentration must be mutually compatible.","The sample follows the Beer-Lambert relationship."],faq:[{question:"Is absorbance dimensionless?",answer:"Absorbance is conventionally reported without a physical unit when compatible inputs are used."},{question:"Does this handle instrument deviations?",answer:"No. It evaluates the stated ideal relationship."}],relatedSlugs:["solution-concentration-calculator"],keywords:["Beer Lambert calculator","absorbance calculator","molar absorptivity"]},
{slug:"titration-calculator",category:"science",shortDescription:"Calculate analyte concentration at equivalence.",intro:"Calculate analyte concentration from titrant concentration, volumes and balanced-reaction stoichiometric coefficients.",formulaExplanation:"Cₐ = CₜVₜνₐ/(Vₐνₜ).",assumptions:["Analyte volume and both stoichiometric coefficients must be positive.","Titrant concentration and volume are non-negative.","The equivalence-point stoichiometry is known."],faq:[{question:"Does this assume a 1:1 reaction?",answer:"No. Explicit titrant and analyte coefficients support other balanced ratios."},{question:"Must volumes use the same units?",answer:"Yes, use compatible volume units so the ratio is valid."}],relatedSlugs:["molarity-calculator","stoichiometry-calculator"],keywords:["titration calculator","equivalence concentration","acid base titration"]}
